/**
 * Nightly batch job that flags open, past-due invoices as Overdue and records
 * a run summary in FB_Job_Summary__c.
 *
 * The job scope is defined in start() with a Database.QueryLocator over
 * FB_Invoice__c records where Status__c = 'Open' and Due_Date__c is before
 * today. Each chunk is updated with partial-success DML
 * (Database.update(records, false)) so that a single invoice that fails to
 * save — for example the validation rule that rejects Overdue invoices with a
 * blank Customer_Email__c — does not prevent the remaining invoices in the
 * chunk from being saved.
 *
 * The class implements Database.Stateful so the running totals (invoices
 * updated, invoices failed, and the sum of Amount__c of the updated invoices)
 * cover every chunk of the job, whatever the batch size. finish() inserts
 * exactly one FB_Job_Summary__c row carrying the totals.
 *
 * @example
 * // Run with the default batch size
 * Database.executeBatch(new OverdueInvoiceBatch());
 *
 * // Run with a custom batch size
 * Database.executeBatch(new OverdueInvoiceBatch(), 50);
 */
public with sharing class OverdueInvoiceBatch implements Database.Batchable<FB_Invoice__c>, Database.Stateful {

    // ─── Constants ───────────────────────────────────────────────────────

    /**
     * Job name recorded on the FB_Job_Summary__c row.
     */
    private static final String JOB_NAME = 'OverdueInvoiceBatch';

    /**
     * SOQL defining the job scope: Open invoices whose Due_Date__c is before
     * today. Only the fields needed for processing and the run totals are
     * selected. A query locator is used so the job scales to large data volumes.
     */
    private static final String OPEN_PAST_DUE_SOQL =
        'SELECT Id, Name, Status__c, Due_Date__c, Amount__c, Customer_Email__c ' +
        'FROM FB_Invoice__c ' +
        'WHERE Status__c = \'Open\' AND Due_Date__c < TODAY ' +
        'ORDER BY Id';

    // ─── Stateful Tracking ───────────────────────────────────────────────

    /**
     * Running count of invoices successfully updated, accumulated across all chunks.
     */
    private Integer recordsUpdated = 0;

    /**
     * Running count of invoices that failed to save, accumulated across all chunks.
     */
    private Integer recordsFailed = 0;

    /**
     * Running sum of Amount__c for successfully updated invoices (blank amounts
     * count as 0), accumulated across all chunks.
     */
    private Decimal overdueAmount = 0;

    // ─── Constructor ─────────────────────────────────────────────────────

    /**
     * Default constructor. The job scope and summary row name are fixed, so no
     * configuration is required.
     */
    public OverdueInvoiceBatch() {
        // No configuration required.
    }

    // ─── Batchable Interface ─────────────────────────────────────────────

    /**
     * Defines the job scope: Open invoices whose Due_Date__c is before today.
     *
     * @param bc Batch context (not used by this job).
     * @return QueryLocator over the invoices to process.
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator(OPEN_PAST_DUE_SOQL);
    }

    /**
     * Marks every invoice in the chunk as Overdue using partial-success DML, so
     * that one invoice that fails to save (for example because of the
     * Customer_Email__c validation rule) does not prevent the other invoices of
     * the chunk from being saved. Updates the running job totals.
     *
     * @param bc Batch context (not used by this job).
     * @param invoices Invoices in the current chunk.
     * @throws OverdueInvoiceBatchException If the chunk update fails for a reason
     *         other than per-record validation/DML errors.
     */
    public void execute(Database.BatchableContext bc, List<FB_Invoice__c> invoices) {
        if (invoices == null || invoices.isEmpty()) {
            return;
        }

        Map<Id, Database.SaveResult> resultsById = markAsOverdue(invoices);
        recordChunkResults(invoices, resultsById);
    }

    /**
     * Inserts exactly one FB_Job_Summary__c row carrying the job totals:
     * records updated, records failed, and the overdue amount of the updated
     * invoices.
     *
     * @param bc Batch context (not used by this job).
     * @throws OverdueInvoiceBatchException If the summary row cannot be inserted.
     */
    public void finish(Database.BatchableContext bc) {
        FB_Job_Summary__c jobSummary = new FB_Job_Summary__c(
            Job_Name__c = JOB_NAME,
            Records_Updated__c = recordsUpdated,
            Records_Failed__c = recordsFailed,
            Overdue_Amount__c = overdueAmount
        );
        try {
            insert jobSummary;
        } catch (Exception ex) {
            throw new OverdueInvoiceBatchException(
                'OverdueInvoiceBatch: failed to insert FB_Job_Summary__c for ' + JOB_NAME +
                ': ' + ex.getMessage(),
                ex
            );
        }
    }

    // ─── Private Helpers ─────────────────────────────────────────────────

    /**
     * Sets Status__c to Overdue on every invoice and saves the chunk with
     * partial-success DML (allOrNone = false), so one failed record does not
     * roll back the rest of the chunk.
     *
     * @param invoices Invoices in the current chunk.
     * @return Map of invoice Id to its SaveResult; SaveResults are returned in
     *         the same order as the records passed in.
     * @throws OverdueInvoiceBatchException If the chunk update fails for a reason
     *         other than per-record validation/DML errors.
     */
    private Map<Id, Database.SaveResult> markAsOverdue(List<FB_Invoice__c> invoices) {
        for (FB_Invoice__c invoice : invoices) {
            invoice.Status__c = 'Overdue';
        }

        try {
            List<Database.SaveResult> saveResults = Database.update(invoices, false);
            Map<Id, Database.SaveResult> resultsById = new Map<Id, Database.SaveResult>();
            for (Database.SaveResult saveResult : saveResults) {
                resultsById.put(saveResult.getId(), saveResult);
            }
            return resultsById;
        } catch (Exception ex) {
            throw new OverdueInvoiceBatchException(
                'OverdueInvoiceBatch: failed to update a chunk of ' + invoices.size() +
                ' invoices: ' + ex.getMessage(),
                ex
            );
        }
    }

    /**
     * Applies the SaveResults to the running totals. A blank Amount__c on a
     * successfully updated invoice counts as 0.
     *
     * @param invoices Invoices in the current chunk.
     * @param resultsById Map of invoice Id to its SaveResult.
     */
    private void recordChunkResults(List<FB_Invoice__c> invoices, Map<Id, Database.SaveResult> resultsById) {
        for (FB_Invoice__c invoice : invoices) {
            Database.SaveResult saveResult = resultsById.get(invoice.Id);
            if (saveResult != null && saveResult.isSuccess()) {
                recordsUpdated++;
                overdueAmount += (invoice.Amount__c ?? 0);
            } else {
                recordsFailed++;
            }
        }
    }

    // ─── Exceptions ──────────────────────────────────────────────────────

    /**
     * Thrown by this job when a failure cannot be recovered from on a
     * per-record basis. Preserves the original cause chain.
     */
    public class OverdueInvoiceBatchException extends Exception {
    }
}
