/**
 * Contact Trigger
 *
 * Thin trigger that only routes events to {@link ContactTriggerHandler}.
 * It contains no SOQL or DML so a bulk insert/update of up to 200 contacts
 * stays within the governor budget (at most 2 SOQL queries and 1 DML
 * statement in total).
 */
trigger ContactTrigger on Contact (before insert, before update, after insert) {
    ContactTriggerHandler handler = new ContactTriggerHandler();

    if (Trigger.isBefore) {
        if (Trigger.isInsert) {
            handler.beforeInsert(Trigger.new);
        } else if (Trigger.isUpdate) {
            handler.beforeUpdate(Trigger.new);
        }
    } else if (Trigger.isAfter && Trigger.isInsert) {
        handler.afterInsert(Trigger.new);
    }
}
