/**
 * Bulk-safe handler for {@link ContactTrigger}.
 *
 * All SOQL and DML live here so the trigger itself stays query/DML free. A
 * bulk insert or update of up to 200 contacts uses at most two SOQL queries
 * (one in the before context, one in the after context) and at most one DML
 * statement in total.
 *
 * Behaviour is preserved from the original trigger:
 *  - Before insert/update: a blank MailingCountry is filled from the parent
 *    account's BillingCountry, and a blank LeadSource is filled from the
 *    parent account's AccountSource on insert only.
 *  - After insert: when a new contact has a phone and its account has none,
 *    the first such contact (in trigger order) sets the account's phone.
 */
public with sharing class ContactTriggerHandler {

    /**
     * Before insert: default a blank MailingCountry from the account's
     * BillingCountry and a blank LeadSource from the account's AccountSource.
     * @param contacts The new contact records being inserted
     */
    public void beforeInsert(List<Contact> contacts) {
        applyAccountDefaults(contacts, true);
    }

    /**
     * Before update: default a blank MailingCountry from the account's
     * BillingCountry. LeadSource is only defaulted on insert.
     * @param contacts The new contact records being updated
     */
    public void beforeUpdate(List<Contact> contacts) {
        applyAccountDefaults(contacts, false);
    }

    /**
     * After insert: set a phone on accounts that still have none, using the
     * first new contact's phone (in trigger order) for each affected account.
     * @param contacts The newly inserted contact records
     */
    public void afterInsert(List<Contact> contacts) {
        // Remember the first contact's phone (in trigger order) per account.
        Map<Id, String> phoneByAccountId = new Map<Id, String>();
        for (Contact c : contacts) {
            if (c.AccountId != null
                    && String.isNotBlank(c.Phone)
                    && !phoneByAccountId.containsKey(c.AccountId)) {
                phoneByAccountId.put(c.AccountId, c.Phone);
            }
        }
        if (phoneByAccountId.isEmpty()) {
            return;
        }

        // One SOQL for every affected account (no per-record queries).
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :phoneByAccountId.keySet()]
        );

        // Only accounts whose phone is still blank get updated.
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : phoneByAccountId.keySet()) {
            Account a = accountsById.get(accountId);
            if (a != null && String.isBlank(a.Phone)) {
                a.Phone = phoneByAccountId.get(accountId);
                accountsToUpdate.add(a);
            }
        }

        // One DML statement for every account that changed.
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    // ─── Private Helpers ─────────────────────────────────────────────────

    /**
     * Applies account-derived defaults to a collection of contacts using a
     * single query.
     * @param contacts The contact records to enrich
     * @param isInsert True when running in the before-insert context (controls
     *                 whether LeadSource is defaulted)
     */
    private void applyAccountDefaults(List<Contact> contacts, Boolean isInsert) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Collect the distinct account ids we need to enrich.
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // One SOQL for every distinct account (no per-record queries).
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }
}
