```apex
/**
 * Re-rates a list of accounts on demand based on AnnualRevenue.
 *
 * Each execution processes at most 200 accounts using one SOQL query and one
 * DML statement. If Ids remain, the execution enqueues a chained
 * AccountScoringJob holding the remaining Ids, so a single start() call can
 * work through up to 50,000 accounts as a chain of jobs.
 *
 * Rating rules:
 *   - AnnualRevenue >= 1,000,000 -> Hot
 *   - AnnualRevenue >= 100,000   -> Warm
 *   - Anything else (including blank) -> Cold
 *
 * @example
 * Id jobId = AccountScoringJob.start(accountIds);
 */
public with sharing class AccountScoringJob implements Queueable {

    /** Maximum number of accounts processed in a single execution. */
    private static final Integer CHUNK_SIZE = 200;

    /** Revenue threshold (USD) at or above which an account is rated Hot. */
    private static final Decimal HOT_THRESHOLD = 1000000;

    /** Revenue threshold (USD) at or above which an account is rated Warm. */
    private static final Decimal WARM_THRESHOLD = 100000;

    /** Ids of the accounts to rate; may be null or empty (in which case execution is a no-op). */
    private final List<Id> accountIds;

    /**
     * Creates a job that will re-rate the given accounts.
     * @param accountIds Ids of the accounts to re-rate. A null or empty list produces a no-op job.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    /**
     * Processes the first up to 200 accounts of this job's list: fetches them in a single
     * SOQL query, derives Rating from AnnualRevenue, and updates only the records whose
     * rating changed in a single DML statement. If Ids remain, enqueues a chained
     * AccountScoringJob carrying the remaining Ids.
     * @param context Queueable execution context (not used).
     * @example
     * System.enqueueJob(new AccountScoringJob(accountIds));
     */
    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Id> chunkIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();
        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < CHUNK_SIZE) {
                chunkIds.add(accountIds.get(i));
            } else {
                remainingIds.add(accountIds.get(i));
            }
        }

        Map<Id, Account> accountById = new Map<Id, Account>(
            [SELECT Id, AnnualRevenue, Rating FROM Account WHERE Id IN :chunkIds WITH USER_MODE]
        );

        List<Account> accountsToUpdate = new List<Account>();
        Set<Id> processedIds = new Set<Id>();
        for (Id accountId : chunkIds) {
            Account account = accountById.get(accountId);
            if (account == null || processedIds.contains(accountId)) {
                continue;
            }
            processedIds.add(accountId);
            String newRating = deriveRating(account.AnnualRevenue);
            if (account.Rating != newRating) {
                account.Rating = newRating;
                accountsToUpdate.add(account);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }

        if (!remainingIds.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }

    /**
     * Enqueues the first job in the scoring chain.
     * @param accountIds Ids of the accounts to re-rate.
     * @return AsyncProcessId of the first job, or null if the list was null or empty.
     * @example
     * Id jobId = AccountScoringJob.start(accountIds);
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    /**
     * Derives the account rating from annual revenue.
     * @param annualRevenue AnnualRevenue of the account; may be null.
     * @return 'Hot' for 1,000,000 or more, 'Warm' for 100,000 or more, 'Cold' otherwise (including null).
     */
    private static String deriveRating(Decimal annualRevenue) {
        if (annualRevenue == null || annualRevenue < WARM_THRESHOLD) {
            return 'Cold';
        }
        if (annualRevenue >= HOT_THRESHOLD) {
            return 'Hot';
        }
        return 'Warm';
    }
}
