```apex
/**
 * Nightly maintenance job that purges expired FB_Integration_Log__c records.
 *
 * Non-ERROR logs are deleted once they are more than 30 days old. Logs whose
 * Level__c is 'ERROR' are retained for 180 days and are only deleted once
 * they are more than 180 days old.
 */
public with sharing class LogPurgeJob implements Schedulable {

    /** Retention window (in days) for non-ERROR logs. */
    private static final Integer STANDARD_RETENTION_DAYS = 30;

    /** Retention window (in days) for ERROR logs. */
    private static final Integer ERROR_RETENTION_DAYS = 180;

    /**
     * Maximum records purged per query batch. Kept below the 50,000-row SOQL
     * result limit so a single query can never hit the limit.
     */
    private static final Integer DELETE_BATCH_SIZE = 49900;

    /**
     * Maximum query batches processed per run. Bounds SOQL consumption (100
     * per transaction); any remaining expired records are picked up by the
     * next nightly run.
     */
    private static final Integer MAX_BATCHES_PER_RUN = 95;

    /**
     * No-argument constructor required by the Schedulable interface.
     */
    public LogPurgeJob() {
    }

    /**
     * Schedules the nightly log purge to run every day at 02:00 in the
     * scheduling user's time zone.
     *
     * @return the CronTrigger Id returned by the scheduling call
     * @throws DuplicateSchedulingException if a job with the same name is already scheduled
     * @example
     * Id cronId = LogPurgeJob.scheduleNightly();
     */
    public static Id scheduleNightly() {
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }

    /**
     * Entry point invoked by the scheduler; delegates to the purge logic.
     *
     * @param context the SchedulableContext for this run (no state is read from it)
     */
    public void execute(SchedulableContext context) {
        purgeExpiredLogs();
    }

    /**
     * Deletes FB_Integration_Log__c records past their retention window:
     * non-ERROR logs older than 30 days and ERROR logs older than 180 days.
     * Runs in bounded batches so a large backlog cannot exceed governor
     * limits; records beyond the per-run cap are purged on the next run.
     */
    private static void purgeExpiredLogs() {
        DateTime standardCutoff = DateTime.now().addDays(-STANDARD_RETENTION_DAYS);
        DateTime errorCutoff = DateTime.now().addDays(-ERROR_RETENTION_DAYS);

        Integer batchesProcessed = 0;
        while (batchesProcessed < MAX_BATCHES_PER_RUN) {
            // Blank (null) levels are treated as non-ERROR and follow the
            // standard 30-day window.
            List<FB_Integration_Log__c> expiredLogs = new List<FB_Integration_Log__c>(
                [
                    SELECT Id
                    FROM FB_Integration_Log__c
                    WITH USER_MODE
                    WHERE ((Level__c != 'ERROR' OR Level__c = NULL) AND CreatedDate < :standardCutoff)
                       OR (Level__c = 'ERROR' AND CreatedDate < :errorCutoff)
                    LIMIT :DELETE_BATCH_SIZE
                ]
            );

            if (expiredLogs.isEmpty()) {
                break;
            }

            // Partial-success DML so one problematic record cannot block the
            // rest of the batch; failed records are retried on later runs.
            Database.delete(expiredLogs, false);

            batchesProcessed++;
            if (expiredLogs.size() < DELETE_BATCH_SIZE) {
                break;
            }
        }
    }
}
