/**
 * Opportunities Domain
 *
 * fflib SObject domain for Opportunity. Validation rules are implemented in
 * the domain's validation hooks, which are invoked by
 * fflib_SObjectDomain.triggerHandler (called from OpportunityTrigger).
 *
 * Rules:
 *  1. On insert and on update, Amount must not be negative.
 *     Error: "Amount cannot be negative."
 *  2. On update, an opportunity that was already Closed Won before the
 *     update cannot have its Amount changed.
 *     Error: "Amount cannot change on a won opportunity."
 *     (Closing the opportunity as won and changing the amount in the same
 *     update is allowed.)
 *
 * All rules are bulk-safe and require no SOQL: the before-update state of
 * each record is taken from the old records passed in by the trigger
 * handler, and each error is only added to the offending record, so other
 * records in the same DML statement still save.
 */
public virtual class Opportunities extends fflib_SObjectDomain {

    /**
     * Standard fflib Constructor inner class, used by the fflib trigger
     * handler to construct the domain.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable {
        /**
         * Build the domain
         */
        public fflib_SObjectDomain constructor() {
            return new Opportunities();
        }
    }

    /**
     * Validation hook for before insert
     */
    public override void beforeInsert(List<SObject> sObjects) {
        for (SObject sObject : sObjects) {
            validateAmount((Opportunity) sObject);
        }
    }

    /**
     * Validation hook for before update
     */
    public override void beforeUpdate(List<SObject> newSObjects, List<SObject> oldSObjects) {
        // Index the before-update state so the comparison is O(n) and needs no SOQL.
        Map<Id, Opportunity> oldOpportunities = new Map<Id, Opportunity>();
        for (SObject oldSObject : oldSObjects) {
            oldOpportunities.put((Id) oldSObject.Id, (Opportunity) oldSObject);
        }
        for (SObject newSObject : newSObjects) {
            Opportunity opportunity = (Opportunity) newSObject;
            // Rule 1: amount must never be negative.
            validateAmount(opportunity);
            // Rule 2: a previously won opportunity cannot change its amount.
            Opportunity oldOpportunity = oldOpportunities.get(opportunity.Id);
            if (oldOpportunity != null
                && oldOpportunity.StageName == 'Closed Won'
                && opportunity.Amount != oldOpportunity.Amount) {
                error('Amount cannot change on a won opportunity.', opportunity, 'Amount');
            }
        }
    }

    /**
     * Validate that the amount is not negative. The error is added to the
     * Amount field of the offending record only, so other records in the
     * same DML statement are not affected.
     */
    private void validateAmount(Opportunity opportunity) {
        if (opportunity.Amount != null && opportunity.Amount < 0) {
            error('Amount cannot be negative.', opportunity, 'Amount');
        }
    }
}
