/**
 * Opportunity Trigger
 *
 * Dispatches all seven trigger events to the fflib SObject domain trigger
 * handler, which constructs the Opportunities domain via its Constructor
 * inner class and invokes its validation hooks.
 */
trigger OpportunityTrigger on Opportunity (
    before insert, before update, before delete,
    after insert, after update, after delete, after undelete
) {
    fflib_SObjectDomain.triggerHandler(
        Opportunities.class,
        Trigger.new,
        Trigger.old,
        Trigger.isInsert,
        Trigger.isUpdate,
        Trigger.isDelete,
        Trigger.isAfter,
        Trigger.isUndelete
    );
}
