/**
 * AccountCountrySync
 *
 * After update on Account: when an account's BillingCountry changes, sync the
 * MailingCountry of its contacts that are blank or still carry the account's
 * previous BillingCountry. Contacts with a different MailingCountry (people
 * who work abroad) are left untouched.
 *
 * Bulk-safe by design (MDM pushes accounts in batches of 200):
 *  - One change-detection pass over Trigger.old / Trigger.new (no DML/SOQL)
 *  - Exactly one SOQL, scoped to the accounts that changed in this transaction
 *  - Exactly one DML (UPDATE) for the whole batch
 *
 * NOTE: we deliberately do NOT load all contacts (the org has ~2.3M).
 * An unfiltered query would blow the 50,000-row synchronous SOQL limit and
 * the 6MB transaction heap. Scoping by AccountId IN :changedAccounts stays
 * within the same "one query, one map" spirit and returns only what we need.
 */
public class AccountCountrySync {

    public static void handle() {
        // 1. Identify accounts whose BillingCountry actually changed, and remember
        //    both the previous and the new country for each of them.
        Map<Id, String> oldCountryByAccountId = new Map<Id, String>();
        Map<Id, String> newCountryByAccountId = new Map<Id, String>();

        for (Integer i = 0; i < Trigger.new.size(); i++) {
            Account updated = Trigger.new[i];
            Account prior = Trigger.old[i];

            if (updated.BillingCountry != prior.BillingCountry) {
                oldCountryByAccountId.put(updated.Id, prior.BillingCountry);
                newCountryByAccountId.put(updated.Id, updated.BillingCountry);
            }
        }

        if (newCountryByAccountId.isEmpty()) {
            return;
        }

        // 2. One query for the whole batch: contacts of the changed accounts only.
        //    Picked from a single result set, no queries in loops.
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact c : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :newCountryByAccountId.keySet()
        ]) {
            String prevCountry = oldCountryByAccountId.get(c.AccountId);

            // Eligible: blank (null or '') or still equal to the previous country.
            if (c.MailingCountry == null
                    || c.MailingCountry == ''
                    || c.MailingCountry == prevCountry) {
                c.MailingCountry = newCountryByAccountId.get(c.AccountId);
                contactsToUpdate.add(c);
            }
        }

        // 3. One DML for the whole batch.
        if (!contactsToUpdate.isEmpty()) {
            UPDATE contactsToUpdate;
        }
    }
}
