import { LightningElement, api } from 'lwc';
import FAVORITE_ADD from '@salesforce/label/c.Favorite_Add';
import FAVORITE_REMOVE from '@salesforce/label/c.Favorite_Remove';

/**
 * An icon-style toggle button that marks a record as a favourite.
 *
 * The `favorite` value is owned by the parent (public property). The parent may
 * change it at any time (for example after a server refresh) and the button
 * always reflects the latest value. Clicking flips the displayed state
 * immediately (optimistic UI) and notifies the parent through the
 * `favoritechange` event.
 */
export default class FavoriteToggle extends LightningElement {
    /**
     * Whether the record is currently a favourite.
     *
     * @type {boolean}
     */
    @api
    favorite = false;

    /**
     * ARIA pressed state, always expressed as the string "true" / "false".
     *
     * @returns {'true'|'false'}
     */
    get ariaPressed() {
        return this.favorite ? 'true' : 'false';
    }

    /**
     * Label describing the action a click performs:
     * - when the record IS a favourite → "Remove from favorites"
     * - when the record is NOT a favourite → "Add to favorites"
     *
     * @returns {string}
     */
    get actionLabel() {
        return this.favorite ? FAVORITE_REMOVE : FAVORITE_ADD;
    }

    /**
     * Button classes. The brand variant is applied while the record is a
     * favourite so the "on" state is visually distinct.
     *
     * @returns {string}
     */
    get buttonClass() {
        return this.favorite
            ? 'slds-button slds-button_icon slds-button_icon-brand'
            : 'slds-button slds-button_icon';
    }

    /**
     * Flips the state optimistically and notifies the parent.
     */
    handleClick() {
        const newFavorite = !this.favorite;
        this.favorite = newFavorite;
        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite: newFavorite }
            })
        );
    }
}
