import { LightningElement, api } from 'lwc';

const OPTION_ID_PREFIX = 'status-listbox-option-';

/**
 * Single-select listbox following the WAI-ARIA listbox pattern.
 *
 * DOM focus stays on the listbox element (tabindex="0"); the "active" option
 * is only referenced through aria-activedescendant and is never focused
 * itself.
 */
export default class StatusListbox extends LightningElement {
    /**
     * Accessible name of the list, used as the listbox aria-label.
     *
     * @type {string}
     */
    @api label;

    _options = [];

    /**
     * Options to display: array of { value, label } objects.
     *
     * @type {Array<{ value: any, label: string }>}
     */
    @api
    get options() {
        return this._options;
    }
    @api
    set options(newValue) {
        this._options = Array.isArray(newValue) ? newValue : [];
        this.syncActiveOption();
    }

    _value = '';

    /**
     * The selected value (may be empty). The parent can change it at any
     * time; the selection is re-rendered and the active option moves to the
     * newly selected option.
     *
     * @type {any}
     */
    @api
    get value() {
        return this._value;
    }
    @api
    set value(newValue) {
        this._value = newValue == null ? '' : newValue;
        this.syncActiveOption();
    }

    /**
     * Index of the active option - the option referenced by
     * aria-activedescendant. The active option may differ from the selected
     * option while the user is navigating.
     *
     * @type {number}
     */
    _activeIndex = 0;

    /**
     * View model for the template: one entry per option with a stable id,
     * the aria-selected attribute value and the active flag.
     *
     * @returns {Array<{ value: any, label: string, id: string, selectedAttr: string, active: boolean }>}
     */
    get optionItems() {
        return this._options.map((option, index) => {
            const selected = option.value === this._value;
            return {
                value: option.value,
                label: option.label,
                id: `${OPTION_ID_PREFIX}${index}`,
                selectedAttr: selected ? 'true' : 'false',
                active: index === this._activeIndex
            };
        });
    }

    /**
     * Id of the active option, bound to aria-activedescendant.
     *
     * @returns {string|undefined}
     */
    get activeOptionId() {
        if (this._activeIndex >= 0 && this._activeIndex < this._options.length) {
            return `${OPTION_ID_PREFIX}${this._activeIndex}`;
        }
        return undefined;
    }

    /**
     * Re-derives the active option: the selected option, or the first
     * option when nothing is selected. Also keeps the active index in
     * range whenever the options change.
     */
    syncActiveOption() {
        if (this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const selectedIndex = this._options.findIndex(
            (option) => option.value === this._value
        );
        this._activeIndex = selectedIndex >= 0 ? selectedIndex : 0;
    }

    /**
     * Keyboard interaction on the listbox. Only the six navigation and
     * selection keys are intercepted; every other key (notably Tab) keeps
     * its default behaviour.
     *
     * @param {KeyboardEvent} event
     */
    handleKeyDown(event) {
        const count = this._options.length;

        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                if (this._activeIndex < count - 1) {
                    this._activeIndex += 1;
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (this._activeIndex > 0) {
                    this._activeIndex -= 1;
                }
                break;
            case 'Home':
                event.preventDefault();
                this._activeIndex = 0;
                break;
            case 'End':
                event.preventDefault();
                if (count > 0) {
                    this._activeIndex = count - 1;
                }
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this.selectOption(this._activeIndex);
                break;
            default:
                // Every other key keeps its default behaviour.
                break;
        }
    }

    /**
     * Clicking an option selects it and makes it the active option.
     *
     * @param {Event} event
     */
    handleOptionClick(event) {
        const clickedValue = event.currentTarget.dataset.value;
        const index = this._options.findIndex(
            (option) => String(option.value) === clickedValue
        );
        if (index < 0) {
            return;
        }
        this.selectOption(index);
        // DOM focus stays on the list so keyboard navigation can continue.
        const listbox = this.template.querySelector('[role="listbox"]');
        if (listbox) {
            listbox.focus();
        }
    }

    /**
     * Selects the option at the given index and makes it the active option.
     * Dispatches a bubbling `change` event with `detail: { value }` only
     * when the selection actually changed.
     *
     * @param {number} index
     */
    selectOption(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }
        this._activeIndex = index;
        if (option.value === this._value) {
            // Already selected: nothing to dispatch.
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                bubbles: true,
                detail: { value: option.value }
            })
        );
    }
}
