```apex
/**
 * Records monthly giving sign-ups from the nonprofit's donation form as
 * Enhanced Recurring Donations (npe03__Recurring_Donation__c).
 *
 * Bulk-safety:
 *  - The entire batch is validated before any DML, so an invalid request
 *    never leaves a partial insert behind.
 *  - All recurring donations are created with a single DML statement and
 *    the service runs zero SOQL queries of its own, so 200 requests cost
 *    exactly 1 DML statement and 0 queries.
 *
 * NPSP's Enhanced Recurring Donation processing generates the installment
 * opportunities itself; this service intentionally never creates
 * Opportunities.
 */
public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31; 31 means "last day of the month"
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final String SCHEDULE_TYPE_RECURRING = 'Recurring';
    private static final String RECURRING_TYPE_RECURRING = 'Recurring';
    private static final String INSTALLMENT_FREQUENCY_MONTHLY = 'Monthly';
    private static final String INSTALLMENT_PERIOD_MONTHLY = '1 Month';
    private static final String STATUS_ACTIVE = 'Active';
    private static final Integer LAST_DAY_OF_MONTH = 31;
    private static final Integer[] DAYS_IN_MONTH = new Integer[] {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

    /**
     * Creates one Enhanced Recurring Donation per request and returns the
     * new recurring donation Ids in request order.
     *
     * @throws RecurringGiftException if any request is invalid; no records
     *         are created in that case.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> newRecurringDonationIds = new List<Id>();
        if (requests == null || requests.isEmpty()) {
            return newRecurringDonationIds;
        }

        // Validate the whole batch before touching the database.
        for (Integer i = 0; i < requests.size(); i++) {
            validateRequest(requests[i], i);
        }

        List<npe03__Recurring_Donation__c> recurringDonations = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest request : requests) {
            recurringDonations.add(buildRecurringDonation(request));
        }

        // The single DML statement for the entire batch.
        insert recurringDonations;

        // Insert preserves list order, so the Ids are returned in request order.
        for (npe03__Recurring_Donation__c recurringDonation : recurringDonations) {
            newRecurringDonationIds.add(recurringDonation.Id);
        }
        return newRecurringDonationIds;
    }

    private static void validateRequest(GiftRequest request, Integer index) {
        if (request == null) {
            throw new RecurringGiftException('Request at index ' + index + ' is null.');
        }
        if (request.contactId == null) {
            throw new RecurringGiftException('Request at index ' + index + ' is missing a contact.');
        }
        if (request.amount == null || request.amount <= 0) {
            throw new RecurringGiftException('Request at index ' + index + ' has a null or non-positive amount.');
        }
        if (request.dayOfMonth == null || request.dayOfMonth < 1 || request.dayOfMonth > 31) {
            throw new RecurringGiftException('Request at index ' + index + ' has a day of month outside 1-31.');
        }
        if (request.startDate == null) {
            throw new RecurringGiftException('Request at index ' + index + ' is missing a start date.');
        }
    }

    private static npe03__Recurring_Donation__c buildRecurringDonation(GiftRequest request) {
        Boolean isOpenEnded = request.installments == null || request.installments == 0;
        Boolean isLastDayOfMonth = request.dayOfMonth == LAST_DAY_OF_MONTH;

        npe03__Recurring_Donation__c recurringDonation = new npe03__Recurring_Donation__c();

        // The contact is the donor.
        recurringDonation.npe03__Contact__c = request.contactId;

        // Every installment is the given amount.
        recurringDonation.npe03__Amount__c = request.amount;

        // Monthly recurring schedule starting on the start date.
        recurringDonation.npe03__Schedule_Type__c = SCHEDULE_TYPE_RECURRING;
        recurringDonation.npsp__RecurringType__c = RECURRING_TYPE_RECURRING;
        recurringDonation.npsp__InstallmentFrequency__c = INSTALLMENT_FREQUENCY_MONTHLY;
        recurringDonation.npe03__Installment_Period__c = INSTALLMENT_PERIOD_MONTHLY;
        recurringDonation.npsp__Day_of_Month__c = request.dayOfMonth;

        // The form's "31" means "last day of the month", which Enhanced
        // Recurring Donations model with the Always Use Last Day of Month
        // flag. Days 1-30 are stored as-is.
        recurringDonation.npsp__Always_Use_Last_Day_Of_Month__c = isLastDayOfMonth;

        recurringDonation.npsp__StartDate__c = request.startDate;
        recurringDonation.npe03__Date_Established__c = request.startDate;
        // The first installment is the start date.
        recurringDonation.npe03__Next_Payment_Date__c = request.startDate;

        if (isOpenEnded) {
            recurringDonation.npe03__Open_Ended_Status__c = true;
            recurringDonation.npe03__Installments__c = null;
            recurringDonation.npsp__EndDate__c = null;
        } else {
            recurringDonation.npe03__Open_Ended_Status__c = false;
            recurringDonation.npe03__Installments__c = request.installments;
            recurringDonation.npsp__EndDate__c = computeEndDate(request.startDate, request.dayOfMonth, request.installments);
        }

        recurringDonation.npsp__Status__c = STATUS_ACTIVE;
        recurringDonation.npsp__PaymentMethod__c = request.paymentMethod;

        return recurringDonation;
    }

    /**
     * Date of the final installment. The k-th installment falls k-1 months
     * after the start date, with the day clamped to the actual number of
     * days in that month (a stored day of 31 means the last day of the
     * month).
     */
    private static Date computeEndDate(Date startDate, Integer dayOfMonth, Integer installments) {
        if (installments == 1) {
            return startDate;
        }
        return applyDayOfMonth(startDate.addMonths(installments - 1), dayOfMonth);
    }

    private static Date applyDayOfMonth(Date date, Integer dayOfMonth) {
        Integer daysInMonth = daysInMonth(date.year(), date.month());
        Integer day = (dayOfMonth == LAST_DAY_OF_MONTH) ? daysInMonth : Math.min(dayOfMonth, daysInMonth);
        return Date.newInstance(date.year(), date.month(), day);
    }

    private static Integer daysInMonth(Integer year, Integer month) {
        if (month == 2 && isLeapYear(year)) {
            return 29;
        }
        return DAYS_IN_MONTH[month - 1];
    }

    private static Boolean isLeapYear(Integer year) {
        return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    }
