/**
 * Trigger Action (TAF 0.3.4): creates an onboarding Task for the owner of
 * newly created "Customer - Direct" and "Customer - Channel" accounts.
 *
 * Runs only in the after insert context. Tasks are built in memory for every
 * qualifying account and inserted with a single DML statement; if no account
 * qualifies, no DML is executed at all.
 */
public with sharing virtual class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    private static final Set<String> ONBOARDING_ACCOUNT_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    public virtual void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        Date activityDate = Date.today().addDays(7);
        List<Task> tasks = new List<Task>();

        for (SObject newRecord : triggerNew) {
            Account account = (Account)newRecord;

            // Accounts with no type, any other type, or no owner get no task.
            if (account.Type != null
                    && ONBOARDING_ACCOUNT_TYPES.contains(account.Type)
                    && account.OwnerId != null) {
                tasks.add(new Task(
                    Subject      = 'Onboard new customer',
                    WhatId       = account.Id,
                    OwnerId      = account.OwnerId,
                    ActivityDate = activityDate,
                    Status       = 'Not Started',
                    Priority     = 'Normal'
                ));
            }
        }

        // Single DML statement per trigger execution, skipped when nothing qualifies.
        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
